import{_ as t,c as o,o as a,ah as n,ao as s,ap as p}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"По ту сторону Радужного моста — завет Бога со всяким живым существом","description":"Радужный мост — красивый образ, но радуга Библии больше: вечный завет, который Бог заключил со всяким живым существом.","frontmatter":{"title":"По ту сторону Радужного моста — завет Бога со всяким живым существом","description":"Радужный мост — красивый образ, но радуга Библии больше: вечный завет, который Бог заключил со всяким живым существом."},"headers":[],"relativePath":"ru/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"ru/pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"ru/pets-in-heaven/rainbow-bridge-covenant.md"};function r(l,e,h,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>«Говорят, он перешёл Радужный мост. Но это просто красивые слова — или есть настоящая надежда?»</p><p class="pl-quote-soft">А вот и удивительное: в Библии действительно есть радуга, и этот завет был заключён ради животных.</p></div><section class="pl-section"><h2>1. Та радуга была заветом с животными</h2><p>После потопа Бог заключил завет с Ноем, обещав больше не уничтожать землю водою. Но сторонами этого завета были не только Ной и его потомки:</p><blockquote><p><strong>Бытие 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>Обратите внимание на слова «<em>всякое живое существо</em>» — птицы, скот и все звери земли названы сторонами завета. И Бог поставил радугу в облаках как знамение <strong>между Ним и землёю, со всяким живым существом</strong>.</p><p>Это один из самых незамеченных и самых нежных фактов всего Писания: <strong>Бог однажды формально и навсегда заключил завет с животными.</strong></p><p>Так что придуманное людьми название «Радужный мост» не так уж далеко от истины. Писание говорит, что этот свет — знамение, а знамение никогда не означает «конец». Оно означает «будет продолжение».</p></section><section class="pl-section"><h2>2. В грядущем мире они лягут в покое</h2><p>Когда Исаия описывает мир, который создаст Бог, животные — в центре картины:</p><blockquote><p><strong>Исаия 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>А Откровение даёт нам услышать, кто поёт в последнем поклонении:</p><blockquote><p><strong>Откровение 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>«Всякое создание» поклоняется. Не только люди.</p><p>А Псалмы подытоживают всё одной короткой строкой:</p><blockquote><p><strong>Псалом 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>Всё, что дышит — включая его, — внутри этой песни.</p></section><section class="pl-section"><h2>3. Значит, по ту сторону моста — обещание</h2><p>Мы не можем добавить обещаний от имени Бога. Но мы можем оставаться внутри того, что Он уже сказал: Он заключил завет со всяким живым существом; в мире, который Он создаст, животные живут в мире; в Его последнем поклонении есть «всякое создание»; всё дышащее будет хвалить Его.</p><p>Эти стихи не говорят: «ваш питомец точно там». Но они делают совершенно законной одну молитву: «Господи, пусть он будет внутри Твоего обещания». И это Бог, Который оставил радугу для животных.</p><p class="pl-quote-soft">Подумайте: если Бог оставил радугу для животных, неужели Он не вспомнит вашего?</p></section><div class="pl-quote"><p>«Ты поставил Свой лук в облаках как знамение со всяким живым существом.<br>Когда я увижу этот свет, я вспомню его.<br>Пусть он будет в покое внутри Твоего обещания, как Ты и обещал.<br>И пусть Твой завет поддержит меня в дни, когда я скучаю. Аминь.»</p></div><section class="pl-section"><h2>Небольшой ритуал для вас</h2><p>Если после дождя появится радуга, пусть это будет вашим знамением. Постойте там несколько секунд и поговорите с ним — не нужно выводов, не нужно договаривать мысль. В Писании этот свет всегда был «знамением завета», а знамение означает, что Бог не забыл.</p><p><a href="/ru/pets-in-heaven/">← Вернуться к Pets in Heaven</a> ｜ Далее: <a href="/ru/pets-in-heaven/permission-to-grieve">Разрешение горевать</a></p></section><div class="pl-cta"><h2>Сохраните места, которые вы видели вместе.</h2><p>Превратите его фотографии в памятную открытку, постер или короткий фильм — чтобы дни, пройденные вместе, обрели форму, которая останется.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Скачать в App Store</a></div><div class="pl-bible"><h3>Пусть слово Писания остаётся с вами</h3><p>Все стихи в этой статье — из Библии. С приложением Rainbow Bible вы можете читать Писание в любое время и настроить виджет со стихом дня — небольшой свет для дней, когда вы скучаете.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Виджет Rainbow Bible со стихом 2 Тимофею 2:13" loading="lazy"><figcaption>Стих дня на главном экране</figcaption></figure><figure><img src="'+p+'" alt="Rainbow Bible — тема «Питомцы на небесах» со стихом Матфея 10:29-31" loading="lazy"><figcaption>Читайте Писание в теме «Питомцы на небесах»</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Скачать Rainbow Bible в App Store</a></div>',8)])])}const f=t(i,[["render",r]]);export{g as __pageData,f as default};
